-- AgentID Trust Desk: Zetaris federation layer (generated by scripts/gen-lightning-sql.ts).
-- Pattern follows zetaris/getting-started open_data/rest_apis (REST table -> CACHE -> SCHEMASTORE VIEW).
-- Run once in the Zetaris SQL Editor (or `npm run zetaris:check -- --apply`).
-- The four internal datasets are SYNTHETIC demo data served from GitHub Pages; in production you would point
-- the same views at the real systems (Postgres CRM, Jira, API-gateway warehouse) with CREATE LIGHTNING DATABASE ... JDBC.

CREATE LIGHTNING DATABASE TRUSTDESK_REST DESCRIBE BY "AgentID Trust Desk sources (REST/JSON)";
CREATE SCHEMASTORE CONTAINER trustdesk;

-- Procurement / vendor-risk register
CREATE LIGHTNING REST TABLE vendor_registry_raw FROM TRUSTDESK_REST REQUEST(
    endpoint "https://jimmywangjimmy.github.io/agentid-trust-desk/data/internal/vendor_registry.json",
    method "get",
    response_type "json",
    http_encoding "URLENCODED"
) HEADER (
) BODY ();
CACHE TABLE TRUSTDESK_REST.vendor_registry_raw;

CREATE SCHEMASTORE VIEW vendor_registry WITH CONTAINER trustdesk AS
SELECT
    r.agent_name AS agent_name,
    r.scorer_agent_id AS scorer_agent_id,
    r.official_agent_id AS official_agent_id,
    r.vendor_org AS vendor_org,
    r.kyb_status AS kyb_status,
    r.contract_status AS contract_status,
    r.declared_owner_wallet AS declared_owner_wallet,
    r.business_owner AS business_owner,
    r.onboarded_at AS onboarded_at,
    r.self_description AS self_description
FROM trustdesk_rest.vendor_registry_raw
LATERAL VIEW explode(records) AS r;

-- CRM customer export
CREATE LIGHTNING REST TABLE customer_wallets_raw FROM TRUSTDESK_REST REQUEST(
    endpoint "https://jimmywangjimmy.github.io/agentid-trust-desk/data/internal/customer_wallets.json",
    method "get",
    response_type "json",
    http_encoding "URLENCODED"
) HEADER (
) BODY ();
CACHE TABLE TRUSTDESK_REST.customer_wallets_raw;

CREATE SCHEMASTORE VIEW customer_wallets WITH CONTAINER trustdesk AS
SELECT
    r.wallet AS wallet,
    r.customer_id AS customer_id,
    r.segment AS segment,
    r.first_order AS first_order,
    r.orders_90d AS orders_90d
FROM trustdesk_rest.customer_wallets_raw
LATERAL VIEW explode(records) AS r;

-- Incident tracker
CREATE LIGHTNING REST TABLE incidents_raw FROM TRUSTDESK_REST REQUEST(
    endpoint "https://jimmywangjimmy.github.io/agentid-trust-desk/data/internal/incidents.json",
    method "get",
    response_type "json",
    http_encoding "URLENCODED"
) HEADER (
) BODY ();
CACHE TABLE TRUSTDESK_REST.incidents_raw;

CREATE SCHEMASTORE VIEW incidents WITH CONTAINER trustdesk AS
SELECT
    r.ticket_id AS ticket_id,
    r.agent_name AS agent_name,
    r.severity AS severity,
    r.category AS category,
    r.opened_at AS opened_at,
    r.status AS status,
    r.summary AS summary
FROM trustdesk_rest.incidents_raw
LATERAL VIEW explode(records) AS r;

-- API gateway analytics
CREATE LIGHTNING REST TABLE gateway_usage_raw FROM TRUSTDESK_REST REQUEST(
    endpoint "https://jimmywangjimmy.github.io/agentid-trust-desk/data/internal/gateway_usage.json",
    method "get",
    response_type "json",
    http_encoding "URLENCODED"
) HEADER (
) BODY ();
CACHE TABLE TRUSTDESK_REST.gateway_usage_raw;

CREATE SCHEMASTORE VIEW gateway_usage WITH CONTAINER trustdesk AS
SELECT
    r.agent_name AS agent_name,
    r.usage_window AS usage_window,
    r.requests AS requests,
    r.error_rate AS error_rate,
    r.out_of_scope_calls AS out_of_scope_calls,
    r.pii_fields_requested AS pii_fields_requested,
    r.rate_limit_hits AS rate_limit_hits,
    r.scopes AS scopes
FROM trustdesk_rest.gateway_usage_raw
LATERAL VIEW explode(records) AS r;

-- Public ERC-8004 registration files (agentURI) for each agent
CREATE LIGHTNING REST TABLE card_goodbot_raw FROM TRUSTDESK_REST REQUEST(
    endpoint "https://talentos-ai.github.io/AgentID/agents/good-bot.json",
    method "get",
    response_type "json",
    http_encoding "URLENCODED"
) HEADER (
) BODY ();
CACHE TABLE TRUSTDESK_REST.card_goodbot_raw;

CREATE LIGHTNING REST TABLE card_fakebot_raw FROM TRUSTDESK_REST REQUEST(
    endpoint "https://talentos-ai.github.io/AgentID/agents/fake-bot.json",
    method "get",
    response_type "json",
    http_encoding "URLENCODED"
) HEADER (
) BODY ();
CACHE TABLE TRUSTDESK_REST.card_fakebot_raw;

CREATE LIGHTNING REST TABLE card_sybilbot_raw FROM TRUSTDESK_REST REQUEST(
    endpoint "https://talentos-ai.github.io/AgentID/agents/sybil-bot.json",
    method "get",
    response_type "json",
    http_encoding "URLENCODED"
) HEADER (
) BODY ();
CACHE TABLE TRUSTDESK_REST.card_sybilbot_raw;

CREATE SCHEMASTORE VIEW agent_cards WITH CONTAINER trustdesk AS
SELECT name AS name, description AS description, active AS active, x402Support AS x402_support, 'https://talentos-ai.github.io/AgentID/agents/good-bot.json' AS agent_uri FROM trustdesk_rest.card_goodbot_raw
UNION ALL
SELECT name AS name, description AS description, active AS active, x402Support AS x402_support, 'https://talentos-ai.github.io/AgentID/agents/fake-bot.json' AS agent_uri FROM trustdesk_rest.card_fakebot_raw
UNION ALL
SELECT name AS name, description AS description, active AS active, x402Support AS x402_support, 'https://talentos-ai.github.io/AgentID/agents/sybil-bot.json' AS agent_uri FROM trustdesk_rest.card_sybilbot_raw;

